def sort_array_by_parity(nums):
    lo, hi = 0, len(nums) - 1

    while lo < hi:
        if nums[lo] % 2 == 0:
            lo += 1
        elif nums[hi] % 2 == 1:
            hi -= 1
        else:
            nums[lo], nums[hi] = nums[hi], nums[lo]
            lo += 1
            hi -= 1

    return nums

